-- v603: atualização do Panorama em 3 turnos (seg–sex, Brasília = UTC−3): 06:50 (já existe), 11:50 e 18:20.
-- Aditiva: só cria agendamentos novos; o segredo interno vem do Vault (diario_cron_secret).
select cron.schedule('rotina-almoco', '50 14 * * 1-5', $c$select net.http_post(url := 'https://wbpsmszecpzioaijfnsl.supabase.co/functions/v1/rotina-cron', headers := jsonb_build_object('Content-Type','application/json','x-cron-secret',(select decrypted_secret from vault.decrypted_secrets where name='diario_cron_secret')), body := '{"acao":"matinal","hm":"11:50"}'::jsonb, timeout_milliseconds := 90000);$c$);
select cron.schedule('rotina-tarde', '20 21 * * 1-5', $c$select net.http_post(url := 'https://wbpsmszecpzioaijfnsl.supabase.co/functions/v1/rotina-cron', headers := jsonb_build_object('Content-Type','application/json','x-cron-secret',(select decrypted_secret from vault.decrypted_secrets where name='diario_cron_secret')), body := '{"acao":"matinal","hm":"18:20"}'::jsonb, timeout_milliseconds := 90000);$c$);
